import type { CSSProperties, HTMLAttributes } from 'react'
import './aurora-background.css'

export interface AuroraBackgroundProps extends HTMLAttributes<HTMLDivElement> {
  /** Duration, in seconds, of one complete drift. */
  speed?: number
  /** Freeze the atmosphere while keeping its color and texture. */
  paused?: boolean
  color1?: string
  color2?: string
  color3?: string
}

function colorOrDefault(value: string, fallback: string) {
  const color = value.trim()
  return color && color.length <= 200 && !/[;{}<>]/.test(color) ? color : fallback
}

/** A slow-moving atmosphere with a separate, readable content layer. */
export function AuroraBackground({
  children,
  className = '',
  speed = 16,
  paused = false,
  color1 = '#e89c62',
  color2 = '#9280da',
  color3 = '#edd1a3',
  style,
  ...props
}: AuroraBackgroundProps) {
  const duration = Number.isFinite(speed) ? Math.min(180, Math.max(2, speed)) : 16

  return (
    <div
      {...props}
      className={`ac-aurora-background ${className}`.trim()}
      data-paused={paused || undefined}
      style={{
        '--ac-aurora-speed': `${duration}s`,
        '--ac-aurora-color-one': colorOrDefault(color1, '#e89c62'),
        '--ac-aurora-color-two': colorOrDefault(color2, '#9280da'),
        '--ac-aurora-color-three': colorOrDefault(color3, '#edd1a3'),
        ...style,
      } as CSSProperties}
    >
      <div className="ac-aurora-field" aria-hidden="true">
        <span className="ac-aurora-band ac-aurora-band-one" />
        <span className="ac-aurora-band ac-aurora-band-two" />
        <span className="ac-aurora-band ac-aurora-band-three" />
      </div>
      <div className="ac-aurora-content">{children}</div>
    </div>
  )
}

.ac-aurora-background {
  position: relative;
  isolation: isolate;
  border-radius: var(--ac-aurora-radius, 0);
  background: var(--ac-aurora-surface, #121110);
  color: var(--ac-aurora-foreground, #f6f2ec);
}

.ac-aurora-field {
  position: absolute;
  z-index: -1;
  inset: 0;
  overflow: hidden;
  border-radius: inherit;
  pointer-events: none;
}

.ac-aurora-field::after {
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(0deg, transparent 0 2px, rgb(255 255 255 / 2.2%) 2px 3px),
    radial-gradient(ellipse at 50% 40%, transparent 15%, rgb(5 5 8 / 60%) 100%);
  content: '';
}

.ac-aurora-band {
  position: absolute;
  display: block;
  width: 95%;
  height: 110%;
  border-radius: 45%;
  filter: blur(clamp(24px, 5vw, 65px));
  opacity: 0.46;
  will-change: transform;
}

.ac-aurora-band-one {
  top: -48%;
  left: -16%;
  background: radial-gradient(ellipse at center, var(--ac-aurora-color-one), transparent 68%);
  animation: ac-aurora-drift-one var(--ac-aurora-speed, 16s) ease-in-out infinite alternate;
}

.ac-aurora-band-two {
  top: -25%;
  right: -32%;
  background: radial-gradient(ellipse at center, var(--ac-aurora-color-two), transparent 68%);
  animation: ac-aurora-drift-two calc(var(--ac-aurora-speed, 16s) * 1.25) ease-in-out infinite alternate;
  animation-delay: calc(var(--ac-aurora-speed, 16s) * -0.5);
}

.ac-aurora-band-three {
  right: -10%;
  bottom: -74%;
  width: 120%;
  background: radial-gradient(ellipse at center, var(--ac-aurora-color-three), transparent 68%);
  opacity: 0.28;
  animation: ac-aurora-drift-three calc(var(--ac-aurora-speed, 16s) * 1.5) ease-in-out infinite alternate;
  animation-delay: calc(var(--ac-aurora-speed, 16s) * -0.8);
}

.ac-aurora-content {
  position: relative;
  z-index: 1;
}

.ac-aurora-background[data-paused] .ac-aurora-band {
  animation-play-state: paused;
  will-change: auto;
}

@keyframes ac-aurora-drift-one {
  from { transform: translate3d(-5%, 2%, 0) rotate(-18deg) scale(1); }
  to { transform: translate3d(35%, 24%, 0) rotate(18deg) scale(1.2, 0.85); }
}

@keyframes ac-aurora-drift-two {
  from { transform: translate3d(8%, -4%, 0) rotate(22deg) scale(1.1); }
  to { transform: translate3d(-32%, 16%, 0) rotate(-24deg) scale(0.85, 1.2); }
}

@keyframes ac-aurora-drift-three {
  from { transform: translate3d(-20%, 6%, 0) rotate(-8deg); }
  to { transform: translate3d(10%, -30%, 0) rotate(16deg); }
}

@media (prefers-reduced-motion: reduce) {
  .ac-aurora-background .ac-aurora-band {
    animation: none;
    will-change: auto;
  }
}

'use client';

import { useEffect, useRef, type ButtonHTMLAttributes, type PointerEvent } from 'react';
import './magnetic-button.css';

export interface MagneticButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** How far the surface follows the pointer, from 0 to 1. */
  strength?: number;
}

/** A stable button hit area with a softly moving visual surface. */
export function MagneticButton({
  children,
  className = '',
  strength = 0.2,
  disabled = false,
  type = 'button',
  onPointerMove,
  onPointerLeave,
  onPointerCancel,
  onFocus,
  ...props
}: MagneticButtonProps) {
  const surfaceRef = useRef<HTMLSpanElement>(null);
  const canAnimateRef = useRef(false);

  const resetPosition = () => {
    if (surfaceRef.current) {
      surfaceRef.current.style.transform = 'translate3d(0, 0, 0)';
    }
  };

  useEffect(() => {
    const preference = window.matchMedia(
      '(hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)',
    );
    const updatePreference = () => {
      canAnimateRef.current = preference.matches;
      if (!preference.matches) resetPosition();
    };

    updatePreference();
    preference.addEventListener('change', updatePreference);
    return () => preference.removeEventListener('change', updatePreference);
  }, []);

  useEffect(() => {
    if (disabled) resetPosition();
  }, [disabled]);

  const moveSurface = (event: PointerEvent<HTMLButtonElement>) => {
    onPointerMove?.(event);
    if (
      event.defaultPrevented ||
      disabled ||
      !canAnimateRef.current ||
      event.pointerType === 'touch' ||
      !surfaceRef.current ||
      event.currentTarget.matches(':focus-visible')
    ) return;

    const bounds = event.currentTarget.getBoundingClientRect();
    const amount = Number.isFinite(strength) ? Math.min(1, Math.max(0, strength)) : 0.2;
    const x = (event.clientX - bounds.left - bounds.width / 2) * amount;
    const y = (event.clientY - bounds.top - bounds.height / 2) * amount;
    surfaceRef.current.style.transform = `translate3d(${x}px, ${y}px, 0)`;
  };

  return (
    <button
      {...props}
      type={type}
      disabled={disabled}
      className={`ac-magnetic-button ${className}`.trim()}
      onPointerMove={moveSurface}
      onPointerLeave={(event) => {
        resetPosition();
        onPointerLeave?.(event);
      }}
      onPointerCancel={(event) => {
        resetPosition();
        onPointerCancel?.(event);
      }}
      onFocus={(event) => {
        resetPosition();
        onFocus?.(event);
      }}
    >
      <span ref={surfaceRef} className="ac-magnetic-button__surface">
        {children}
      </span>
    </button>
  );
}

export default MagneticButton;

.ac-magnetic-button {
  position: relative;
  display: inline-grid;
  min-height: 44px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--ac-ink, #171914);
  font: inherit;
  text-decoration: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.ac-magnetic-button__surface {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75em;
  min-height: inherit;
  padding: 0.9em 1.45em;
  border: 1px solid transparent;
  border-radius: inherit;
  background: var(--ac-accent, #d5fa55);
  color: inherit;
  font-weight: 600;
  line-height: 1.15;
  pointer-events: none;
  transition: transform 380ms cubic-bezier(0.2, 0.8, 0.2, 1), background-color 180ms ease;
}

.ac-magnetic-button:hover .ac-magnetic-button__surface {
  background: var(--ac-accent-hover, #c7ee43);
}

.ac-magnetic-button:active .ac-magnetic-button__surface {
  transform: translate3d(0, 0, 0) scale(0.98) !important;
}

.ac-magnetic-button:focus-visible {
  outline: 2px solid var(--ac-focus, #6d782e);
  outline-offset: 5px;
}

.ac-magnetic-button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.ac-magnetic-button:disabled .ac-magnetic-button__surface {
  transform: none !important;
}

@media (prefers-reduced-motion: reduce), (pointer: coarse) {
  .ac-magnetic-button__surface {
    transform: none !important;
    transition: background-color 180ms ease;
  }
}

'use client';

import { useEffect, useRef, useState, type CSSProperties } from 'react';
import './split-text.css';

export interface SplitTextProps {
  text: string;
  className?: string;
  /** The stagger between words, in seconds. */
  delay?: number;
  /** Change this value to replay the reveal. */
  replayKey?: number;
  as?: 'h1' | 'h2' | 'h3' | 'p' | 'span';
}

/** Reveals words once on entry while preserving one complete screen reader phrase. */
export function SplitText({
  text,
  className = '',
  delay = 0.06,
  replayKey = 0,
  as: Element = 'p',
}: SplitTextProps) {
  const textRef = useRef<HTMLSpanElement>(null);
  const [visible, setVisible] = useState(false);
  const stagger = Number.isFinite(delay) ? Math.max(0, delay) : 0.06;
  let wordIndex = 0;

  useEffect(() => {
    const element = textRef.current;
    if (!element) return;
    setVisible(false);

    const preference = window.matchMedia('(prefers-reduced-motion: reduce)');
    let frame = 0;
    let observer: IntersectionObserver | undefined;
    const reveal = () => {
      frame = window.requestAnimationFrame(() => setVisible(true));
      observer?.disconnect();
    };
    const handlePreference = () => {
      if (preference.matches) reveal();
    };

    if (preference.matches || !('IntersectionObserver' in window)) {
      reveal();
    } else {
      observer = new IntersectionObserver(
        (entries) => {
          if (entries.some((entry) => entry.isIntersecting)) reveal();
        },
        { threshold: 0.1 },
      );
      observer.observe(element);
    }

    preference.addEventListener('change', handlePreference);
    return () => {
      window.cancelAnimationFrame(frame);
      observer?.disconnect();
      preference.removeEventListener('change', handlePreference);
    };
  }, [text, replayKey]);

  return (
    <Element className={`ac-split-text ${className}`.trim()} data-visible={visible}>
      <span className="ac-split-text__accessible">{text}</span>
      <span ref={textRef} className="ac-split-text__visual" aria-hidden="true">
        {text.split(/(\s+)/).map((part, index) => {
          if (/^\s+$/.test(part)) return part;
          if (!part) return null;
          const style = { '--ac-word-delay': `${wordIndex++ * stagger}s` } as CSSProperties;
          return (
            <span className="ac-split-text__mask" key={`${replayKey}-${index}`}>
              <span className="ac-split-text__word" style={style}>{part}</span>
            </span>
          );
        })}
      </span>
    </Element>
  );
}

export default SplitText;

.ac-split-text {
  color: var(--ac-ink, #171914);
}

.ac-split-text__accessible {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.ac-split-text__visual {
  white-space: pre-wrap;
}

.ac-split-text__mask {
  display: inline-block;
  padding-bottom: 0.12em;
  margin-bottom: -0.12em;
  overflow: hidden;
  vertical-align: top;
}

.ac-split-text__word {
  display: inline-block;
  opacity: 0;
  transform: translate3d(0, 112%, 0) rotate(3deg);
  transform-origin: left bottom;
  transition: transform 800ms cubic-bezier(0.2, 0.75, 0.2, 1), opacity 500ms ease;
  transition-delay: var(--ac-word-delay, 0s);
}

.ac-split-text[data-visible='true'] .ac-split-text__word {
  opacity: 1;
  transform: translate3d(0, 0, 0) rotate(0);
}

@media (prefers-reduced-motion: reduce) {
  .ac-split-text__word {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

import type { CSSProperties, HTMLAttributes, ReactNode } from 'react'
import './gradient-text.css'

export interface GradientTextProps extends HTMLAttributes<HTMLSpanElement> {
  children: ReactNode
  /** At least two CSS colors, arranged in reading order. */
  colors?: string[]
  /** Duration in seconds of one color sweep. */
  speed?: number
  paused?: boolean
}

const defaultColors = ['#ef9b61', '#f7e6cf', '#b8a0e9', '#ef9b61']

/** Keeps its text in the document while animating only its painted color. */
export function GradientText({
  children,
  className = '',
  colors = defaultColors,
  speed = 8,
  paused = false,
  style,
  ...props
}: GradientTextProps) {
  const safeColors = colors
    .filter((color) => typeof color === 'string' && color.trim() && color.length <= 200 && !/[;{}<>]/.test(color))
    .slice(0, 8)
  const palette = safeColors.length >= 2 ? safeColors : defaultColors
  const duration = Number.isFinite(speed) ? Math.min(180, Math.max(1, speed)) : 8

  return (
    <span
      {...props}
      className={`ac-gradient-text ${className}`.trim()}
      data-paused={paused || undefined}
      style={{
        '--ac-gradient-text-colors': palette.join(', '),
        '--ac-gradient-text-speed': `${duration}s`,
        ...style,
      } as CSSProperties}
    >
      {children}
    </span>
  )
}

.ac-gradient-text {
  color: var(--ac-gradient-text-fallback, #efb281);
}

@supports ((background-clip: text) or (-webkit-background-clip: text)) {
  .ac-gradient-text {
    background-image: linear-gradient(110deg, var(--ac-gradient-text-colors, #ef9b61, #f7e6cf, #b8a0e9, #ef9b61));
    background-size: 250% 100%;
    background-position: 0% center;
    background-clip: text;
    -webkit-background-clip: text;
    color: transparent;
    -webkit-text-fill-color: transparent;
    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
    animation: ac-gradient-text-flow var(--ac-gradient-text-speed, 8s) ease-in-out infinite alternate;
  }
}

.ac-gradient-text[data-paused] {
  animation-play-state: paused;
}

@keyframes ac-gradient-text-flow {
  from { background-position: 0% center; }
  to { background-position: 100% center; }
}

@media (prefers-reduced-motion: reduce) {
  .ac-gradient-text {
    animation: none;
    background-size: 100% 100%;
  }
}

@media (forced-colors: active) {
  .ac-gradient-text {
    background: none;
    color: CanvasText;
    -webkit-text-fill-color: CanvasText;
  }
}

@media print {
  .ac-gradient-text {
    background: none;
    color: currentColor;
    -webkit-text-fill-color: currentColor;
  }
}

'use client'

import type { CSSProperties, HTMLAttributes, PointerEvent } from 'react'
import './spotlight-card.css'

export interface SpotlightCardProps extends HTMLAttributes<HTMLDivElement> {
  /** The accent color of the light that follows the pointer. */
  color?: string
}

export function SpotlightCard({
  children,
  className = '',
  color = '#d7ee9e',
  style,
  onPointerMove,
  onPointerLeave,
  onPointerCancel,
  ...props
}: SpotlightCardProps) {
  function moveLight(event: PointerEvent<HTMLDivElement>) {
    onPointerMove?.(event)
    if (
      event.defaultPrevented ||
      event.pointerType !== 'mouse' ||
      window.matchMedia('(prefers-reduced-motion: reduce)').matches
    ) return

    const bounds = event.currentTarget.getBoundingClientRect()
    event.currentTarget.style.setProperty('--ac-spotlight-x', `${event.clientX - bounds.left}px`)
    event.currentTarget.style.setProperty('--ac-spotlight-y', `${event.clientY - bounds.top}px`)
  }

  function resetLight(event: PointerEvent<HTMLDivElement>) {
    onPointerLeave?.(event)
    event.currentTarget.style.removeProperty('--ac-spotlight-x')
    event.currentTarget.style.removeProperty('--ac-spotlight-y')
  }

  return (
    <div
      {...props}
      className={`ac-spotlight-card ${className}`.trim()}
      style={{ '--ac-spotlight-color': color, ...style } as CSSProperties}
      onPointerMove={moveLight}
      onPointerLeave={resetLight}
      onPointerCancel={(event) => {
        onPointerCancel?.(event)
        event.currentTarget.style.removeProperty('--ac-spotlight-x')
        event.currentTarget.style.removeProperty('--ac-spotlight-y')
      }}
    >
      {children}
    </div>
  )
}

.ac-spotlight-card {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border: 1px solid var(--ac-card-border, rgb(255 255 255 / 12%));
  border-radius: var(--ac-card-radius, 16px);
  background: var(--ac-card-surface, #191b18);
  color: var(--ac-card-color, #e9e9df);
}

.ac-spotlight-card::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    480px circle at var(--ac-spotlight-x, 50%) var(--ac-spotlight-y, 50%),
    color-mix(in srgb, var(--ac-spotlight-color) 20%, transparent),
    transparent 72%
  );
  opacity: 0;
  transition: opacity 300ms ease;
  pointer-events: none;
  content: '';
}

.ac-spotlight-card:hover::before,
.ac-spotlight-card:focus-within::before {
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  .ac-spotlight-card {
    --ac-spotlight-x: 50% !important;
    --ac-spotlight-y: 50% !important;
  }

  .ac-spotlight-card::before {
    transition: none;
  }
}

@media (hover: none) {
  .ac-spotlight-card::before {
    opacity: 0.65;
  }
}

'use client'

import type { CSSProperties, HTMLAttributes, PointerEvent } from 'react'
import './tilt-card.css'

export interface TiltCardProps extends HTMLAttributes<HTMLDivElement> {
  /** Maximum rotation in degrees, from 0 to 30. */
  maxRotation?: number
  /** Distance to the viewer in pixels. */
  perspective?: number
}

export function TiltCard({
  children,
  className = '',
  maxRotation = 8,
  perspective = 900,
  style,
  onPointerMove,
  onPointerLeave,
  onPointerCancel,
  ...props
}: TiltCardProps) {
  const rotation = Number.isFinite(maxRotation) ? Math.max(0, Math.min(30, maxRotation)) : 8
  const depth = Number.isFinite(perspective) ? Math.max(100, perspective) : 900

  function resetTilt(element: HTMLDivElement) {
    element.style.removeProperty('--ac-tilt-x')
    element.style.removeProperty('--ac-tilt-y')
  }

  function tilt(event: PointerEvent<HTMLDivElement>) {
    onPointerMove?.(event)
    if (
      event.defaultPrevented ||
      event.pointerType !== 'mouse' ||
      window.matchMedia('(prefers-reduced-motion: reduce), (pointer: coarse)').matches
    ) return

    const bounds = event.currentTarget.getBoundingClientRect()
    if (!bounds.width || !bounds.height) return
    const x = Math.max(-1, Math.min(1, ((event.clientX - bounds.left) / bounds.width - 0.5) * 2))
    const y = Math.max(-1, Math.min(1, ((event.clientY - bounds.top) / bounds.height - 0.5) * 2))
    event.currentTarget.style.setProperty('--ac-tilt-x', `${-y * rotation}deg`)
    event.currentTarget.style.setProperty('--ac-tilt-y', `${x * rotation}deg`)
  }

  return (
    <div
      {...props}
      className={`ac-tilt-card ${className}`.trim()}
      style={{ '--ac-tilt-perspective': `${depth}px`, ...style } as CSSProperties}
      onPointerMove={tilt}
      onPointerLeave={(event) => {
        onPointerLeave?.(event)
        resetTilt(event.currentTarget)
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event)
        resetTilt(event.currentTarget)
      }}
    >
      {children}
    </div>
  )
}

.ac-tilt-card {
  position: relative;
  border: 1px solid var(--ac-card-border, rgb(255 255 255 / 12%));
  border-radius: var(--ac-card-radius, 16px);
  background: var(--ac-card-surface, #191b18);
  color: var(--ac-card-color, #e9e9df);
  transform: perspective(var(--ac-tilt-perspective, 900px)) rotateX(var(--ac-tilt-x, 0deg)) rotateY(var(--ac-tilt-y, 0deg));
  transform-style: preserve-3d;
  transition: transform 200ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.ac-tilt-card:focus-within {
  outline: 2px solid var(--ac-focus-color, #d7ee9e);
  outline-offset: 5px;
}

@media (prefers-reduced-motion: reduce), (pointer: coarse), (hover: none) {
  .ac-tilt-card {
    transform: none;
    transition: none;
  }
}

import type { CSSProperties, HTMLAttributes } from 'react'
import './border-beam.css'

export interface BorderBeamProps extends HTMLAttributes<HTMLDivElement> {
  /** Seconds for the light to travel once around the edge. */
  duration?: number
  color?: string
  paused?: boolean
}

/** A luminous edge that leaves child content and focus outlines unobstructed. */
export function BorderBeam({
  children,
  className = '',
  duration = 8,
  color = '#f19451',
  paused = false,
  style,
  ...props
}: BorderBeamProps) {
  const seconds = Number.isFinite(duration) ? Math.min(180, Math.max(1, duration)) : 8
  const beamColor = color.trim()
  const safeColor = beamColor && beamColor.length <= 200 && !/[;{}<>]/.test(beamColor)
    ? beamColor
    : '#f19451'

  return (
    <div
      {...props}
      className={`ac-border-beam ${className}`.trim()}
      data-paused={paused || undefined}
      style={{
        '--ac-border-beam-duration': `${seconds}s`,
        '--ac-border-beam-color': safeColor,
        ...style,
      } as CSSProperties}
    >
      {children}
    </div>
  )
}

@property --ac-border-beam-angle {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}

.ac-border-beam {
  position: relative;
  isolation: isolate;
  border: 1px solid var(--ac-border-beam-border, rgb(255 255 255 / 13%));
  border-radius: var(--ac-border-beam-radius, 18px);
  background: var(--ac-border-beam-surface, #191817);
  color: var(--ac-border-beam-foreground, #f4efe8);
}

.ac-border-beam::after {
  position: absolute;
  z-index: 1;
  inset: -1px;
  padding: var(--ac-border-beam-width, 1px);
  border-radius: inherit;
  background: conic-gradient(
    from var(--ac-border-beam-angle),
    transparent 0deg 220deg,
    var(--ac-border-beam-color, #f19451) 290deg,
    #fff4e4 315deg,
    transparent 320deg 360deg
  );
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask-composite: exclude;
  animation: ac-border-beam-orbit var(--ac-border-beam-duration, 8s) linear infinite;
  pointer-events: none;
  content: '';
}

.ac-border-beam[data-paused]::after {
  animation-play-state: paused;
}

